messages.content:
Tool response:
Tool: place_proxy_bid
Description: Place Proxy Bid
Parameters:
    {
      "type": "object",
      "properties": {
        "auction_id": {
          "type": "integer",
          "description": "The ID of the auction to place the bid on",
          "title": "Auction Id"
        },
        "amount": {
          "type": "number",
          "title": "Amount",
          "description": "The amount of the bid ($120)"
        },
        "max_auto_bid": {
          "type": "number",
          "title": "Max Auto Bid",
          "description": "The maximum amount the system can automatically bid on behalf of the user ($150)"
        }
      },
      "required": [
        "auction_id",
        "amount",
        "max_auto_bid"
      ]
    }
